PUBLIC=ROOT/'docs/research/gcts-rl-renewal'
def esc(x):return html.escape(str(x))
def math(x):return '\\('+esc(x)+'\\)'
def number(n):return math(str(n))
def seconds(n):return math(f'{n:.6f}')
def tex(f,m):
    h=f[0]
    if h=='var':return ('x_{'+f[1][1:]+'}') if f[1].startswith('X') else ('v_{'+f[1][1:]+'}' if f[1].startswith('V') else r'\mathrm{'+f[1].replace('_',r'\_')+'}')
    if h=='fun':
        original={v:k for k,v in m['functions'].items()}.get(f[1]);args=[tex(t,m) for t in f[2]]
        if original=='zero':return '0'
        if original=='succ':return 'S('+args[0]+')'
        if original=='add':return r'\bigl('+args[0]+'+'+args[1]+r'\bigr)'
        if f[1] in m.get('witness_names',{}):name=m['witness_names'][f[1]]
        elif f[1].startswith('esk'):name=r'\operatorname{'+f[1].replace('_',r'\_')+'}'
        else:name=r'\operatorname{'+(original or f[1]).replace('_',r'\_')+'}'
        return name+('('+','.join(args)+')' if args else '')
    if h=='eq':return tex(f[1],m)+'='+tex(f[2],m)
    if h in ('bot','top'):return r'\bot' if h=='bot' else r'\top'
    if h=='not':return r'\neg\bigl('+tex(f[1],m)+r'\bigr)'
    if h in ('and','or','imp'):return r'\bigl('+tex(f[1],m)+{'and':r'\land ','or':r'\lor ','imp':r'\Rightarrow '}[h]+tex(f[2],m)+r'\bigr)'
    if h in ('forall','exists'):return (r'\forall ' if h=='forall' else r'\exists ')+tex(('var',f[1]),m)+r'\;\bigl('+tex(f[2],m)+r'\bigr)'
    raise ValueError('unsupported reader formula '+h)

def meaning(r,ch,numbers):
    source=r['source'];n=r['name']
    if source['head']=='file':
        original=ch['original_name']
        return {'AZ':'Adding zero on the right leaves an arbitrary object unchanged.',
                'AS':'Adding a successor on the right is the successor of the preceding sum.',
                'explicit declared nat-induction instance':'The explicitly supplied induction instance: the base equality and a universal successor step imply the universal equality.',
                'target':'The desired left-zero identity. This line is the conjecture, not an assumed fact.'}.get(original,'Exact supplied input '+esc(original)+'.')
    ps=', '.join(str(numbers[p]) for p in ch.get('parents',[]));rule=source['args'][0]
    if rule=='assume_negation':return 'Assume the universal target is false and seek a contradiction; a counterexample must therefore exist.'
    if 'reconstruction' in ch:
        witness=next(iter(ch['extension']['introduced_functions']))
        if n=='c_0_4':return 'Replace the induction premise’s existential failure witness by a globally fresh '+math('w_{1}')+'. The displayed alternatives say that a failed base or successor step can block induction; otherwise the desired equality holds for every object. The fresh witness is an auxiliary symbol, not a new original axiom.'
        return 'Name the counterexample to the universal target by the globally fresh '+math('w_{2}')+'. Its inequality retains the negated goal; this is a conservative witness extension, not an ordinary logical consequence in the old signature.'
    explanations={
        'c_0_5':'Rename the bound variable in the right-zero axiom.',
        'c_0_6':'Extract the first universal clause from the transformed induction instance.',
        'c_0_7':'Read the right-zero axiom as a universally quantified clause.',
        'c_0_8':'Rename the two bound variables in the successor axiom.',
        'c_0_9':'The base case is true by the right-zero axiom, so remove the failed-base alternative.',
        'c_0_11':'Read the successor axiom as a universally quantified clause.',
        'c_0_12':'The universal clause forces the equality at '+math('w_{1}')+': a supposed inequality at that same object contradicts the clause.',
        'c_0_14':'Extract the second universal clause from the transformed induction instance.',
        'c_0_15':'Apply the successor axiom to the established equality at '+math('w_{1}')+' to obtain the equality at its successor.',
        'c_0_16':'Read the named counterexample inequality as a clause.',
        'c_0_17':'The base and successor equalities remove both failure alternatives. The equality now holds for every object.',
        'c_0_18':'Instantiate that universal equality at the named counterexample. Equality and inequality conflict, completing the refutation.'}
    return explanations.get(n,'Derive the displayed formula from the listed parent lines.')+' Parents: '+esc(ps)+'.'

def panel(o,m,text,index):
    check=o['proof_check']['result'];m={**m,'witness_names':{n:'w_{'+str(i+1)+'}' for i,n in enumerate(check['introductions'])}};rs=records(text);nums={r['name']:i+1 for i,r in enumerate(rs)};parts=['<article class="proof-panel" id="proof-'+str(index)+'"'+(' hidden' if index else '')+'>']
    parts.append('<p><strong>'+('Original finite theory' if o['kind']=='theory' else 'Theory and all admitted interfaces')+'</strong> · repetition '+number(o['repetition'])+' · '+number(len(rs))+' returned lines. No lemma input was selected.</p>')
    parts.append('<p class="small">Display aliases in this run: '+', '.join(math(alias)+' denotes actual <code>'+esc(name)+'</code>' for name,alias in m['witness_names'].items())+'. This display renaming changes no checked formula or saved certificate.</p>')
    for i,(r,ch) in enumerate(zip(rs,check['checks'])):
        boundary=' boundary' if 'reconstruction' in ch else ''
        parts.append('<div class="proof-line'+boundary+'"><span class="line-number">'+str(i+1)+'</span><div><div class="formula">'+math(tex(r['formula'],m))+'</div><p>'+meaning(r,ch,nums)+'</p><p class="small"><code>'+esc(r['name'])+'</code> · '+esc(ch['status'])+'</p>')
        if 'reconstruction' in ch:
            c=ch['reconstruction'];parts.append('<details class="reconstruction"><summary>Inspect the conservative-extension boundary</summary><p>The checker supplies this explicit replacement derivation for the compressed printed annotation. It certifies the compound parent-to-child relation; E’s unprinted implementation intermediates are not claimed to be reproduced verbatim.</p><div class="mini-flow"><div><strong>Equivalent parent NNF</strong><div class="formula">'+math(tex(frozen(c['normalized_parent']),m))+'</div></div><div><strong>Strict fresh witness formula</strong><div class="formula">'+math(tex(frozen(c['witness_formula']),m))+'</div></div><div><strong>Displayed child</strong><div class="formula">'+math(tex(r['formula'],m))+'</div></div></div><p>Lexical existential sites determine every witness argument. All original symbols and all earlier witnesses are reserved. The unchanged strict prototype checks freshness, scope and arity; the final displayed child has its own replayed consequence certificate.</p></details>')
        parts.append('<details><summary>Exact TSTP source and independent certificate</summary><pre>'+esc(json.dumps(dict(source=r['source'],check=ch),indent=2))+'</pre></details></div></div>')
    parts.append('<details><summary>Complete actual E output</summary><pre>'+esc(text)+'</pre></details></article>');return ''.join(parts)

def main():
    started=time.perf_counter();plan=unchanged();summary=load(OUT/'summary.json');audit=load(OUT/'audit.json');setup=load(OUT/'setup.json');authority=load(OUT/'native-authority.json');bundle=load(OUT/'bundle.json')
    if audit['status']!='passed' or audit['plan_sha256']!=sha((OUT/'plan.json').read_bytes()) or audit['summary_sha256']!=sha((OUT/'summary.json').read_bytes()) or audit['setup_sha256']!=sha((OUT/'setup.json').read_bytes()):raise ValueError('exact completed evidence audit')
    observations=summary['observations'];mapping=load(OUT/'arithmetic-theory.mapping.json');assertion=bundle['plan']['assertion'];statements=[]
    for label,f in [*assertion['theory']['axioms'].items(),('Explicit finite induction instance',bundle['schemas'][0]['formula']),('Target',assertion['target'])]:
        statements.append('<p><strong>'+esc(label)+'</strong></p><div class="formula">'+math(tex(native_formula(f,mapping),mapping))+'</div>')
    options=[];panels=[]
    for i,o in enumerate(observations):
        path=OUT/('arithmetic-'+o['kind']+'.p');m=load(path.with_suffix('.mapping.json'));text=(OUT/('arithmetic-'+o['kind']+'-r'+str(o['repetition'])+'.tstp')).read_text()
        options.append('<option value="'+str(i)+'">'+('Theory only' if o['kind']=='theory' else 'Full admitted library')+' · run '+str(o['repetition'])+'</option>');panels.append(panel(o,m,text,i))
    rows=[]
    for o in observations:
        rows.append('<tr><td>'+('Theory only' if o['kind']=='theory' else 'Full library')+'</td><td>'+number(o['repetition'])+'</td><td>'+seconds(o['e_measurement']['wall_seconds']*1000)+'</td><td>'+seconds(o['proof_check']['operation_seconds']*1000)+'</td><td>'+seconds(o['proof_replay']['operation_seconds']*1000)+'</td><td>'+number(o['proof_steps'])+'</td><td>'+number(len(o['used_lemma_inputs']))+'</td></tr>')
    inventory=[]
    for e,r in zip(bundle['interfaces'],setup['interfaces']):
        inventory.append('<details><summary><code>'+esc(e['id'])+'</code> · '+esc(', '.join(e['axiom_dependencies']+e['induction_dependencies']) or 'logical interface')+'</summary><div class="formula">'+math(tex(native_formula(e['formula'],mapping),mapping))+'</div><p>Original admitted definition <code>'+esc(e['original_name'])+'</code>. Full admission binding and certificate are preserved in the downloadable evidence.</p><pre>'+esc(json.dumps(e,indent=2))+'</pre></details>')
    e_seconds=sum(o['e_measurement']['wall_seconds'] for o in observations);check_seconds=sum(o['proof_check']['operation_seconds'] for o in observations);replay_seconds=sum(o['proof_replay']['operation_seconds'] for o in observations)
    failed=load(OUT/'attempt-02/summary.json');old_e=sum(o['e_measurement']['wall_seconds'] for o in failed['observations']);old_check=sum(o['proof_check']['operation_seconds'] for o in failed['observations'])
    costs=[('Exact input/provenance preparation',plan['preparation_seconds'],'seconds'),('Fresh complete-library setup, saved progress timer',setup['seconds'],'seconds'),('Fresh pre-run replay of every interface',summary['interface_pre_run_replay_seconds'],'seconds'),('Four E binary executions',e_seconds,'seconds'),('Four complete-check worker operations',check_seconds,'seconds'),('Four fresh full-replay worker operations',replay_seconds,'seconds'),('Target batch orchestration including worker startup/serialization',summary['run_seconds'],'seconds'),('Independent saved-evidence/corruption audit',audit['seconds'],'seconds'),('Reused original native admission/search/check execution',authority['original_native_seconds'],'seconds'),('Reused full native computation audits',authority['independent_native_audit_seconds'],'seconds'),('Peak E resident memory',max(o['e_measurement']['peak_rss_bytes'] for o in observations)/1048576,'MiB'),('Peak fresh target-check/replay worker memory',max(o[k]['peak_rss_bytes'] for o in observations for k in ('proof_check','proof_replay'))/1048576,'MiB'),('Peak all-interface setup worker memory',max(r['measurement']['peak_rss_bytes'] for r in setup['interfaces'])/1048576,'MiB')]
    cost_html='<table><thead><tr><th>Measured operation or disclosed reuse</th><th>Cost</th><th>Unit</th></tr></thead><tbody>'+''.join('<tr><td>'+label+'</td><td>'+seconds(value)+'</td><td>'+unit+'</td></tr>' for label,value,unit in costs)+'</tbody></table>'
    page=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Arithmetic induction · checked external control</title><link rel="stylesheet" href="report.css?v=20261011-eit1"><script>window.MathJax={tex:{inlineMath:[['\\(','\\)']],displayMath:[['\\[','\\]']]},options:{skipHtmlTags:['script','noscript','style','textarea','pre','code']}};</script><script defer src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-chtml.js"></script><style>.intro{margin-top:42px}h1{font-size:clamp(40px,5vw,64px)}.small{font-size:12px;line-height:1.7}.formula{font-size:18px;overflow:auto;max-width:100%;margin:14px 0}.proof-line{display:grid;grid-template-columns:34px minmax(0,1fr);gap:15px;padding:18px 0;border-bottom:1px solid var(--line)}.line-number{font-size:12px;color:var(--muted)}.boundary{border-left:4px solid #b38843;padding-left:12px;background:#faf5e9}.mini-flow{display:grid;grid-template-columns:minmax(0,1fr);gap:12px}.mini-flow>div{padding:14px;border-left:3px solid #377fa0;background:#f2f5ec}.mini-flow>div:nth-child(2){border-color:#b38843}.flow{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:25px 0}.flow>div{padding:20px;border-top:4px solid #377fa0;background:#f2f5ec}.flow strong{display:block;margin-bottom:9px}.scroll-table{overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px}th,td{text-align:left;padding:10px;border-bottom:1px solid var(--line)}pre{font-size:11px;white-space:pre;overflow:auto;max-height:400px}details{margin:14px 0}select{max-width:100%}[hidden]{display:none!important}@media(max-width:650px){.flow{grid-template-columns:1fr}.proof-line{grid-template-columns:22px minmax(0,1fr);gap:8px}}</style></head><body><header class="masthead"><a href="./">GCTS + RL · Research notebook</a><span>EXTERNAL ARITHMETIC CONTROL · FINITE INDUCTION</span></header><main><section class="intro"><p class="eyebrow">UNIVERSAL TARGET · AUTOMATIC SEARCH · CHECKED WITNESS EXTENSIONS</p><h1>Induction, with every<br>returned line checked.</h1><p class="deck">E automatically proves the same universal left-zero identity. It selects no supplied lemma in either inventory lane.</p><p>All four fresh runs pass a complete separate first-order certificate check and a fresh serialized full replay. Each derivation has \(19\) displayed lines, including two globally fresh conservative witness extensions. The exact inputs are two recursive arithmetic axioms and the one mechanically exported, predeclared induction instance. The library lane additionally includes every one of the \(66\) admitted interfaces.</p><p><strong>This is a finite induction-instance control.</strong> The native <code>nat-induction</code> schema supports predicates beyond this catalog; E receives only the complete declared finite instance inventory for this target. No full Peano arithmetic comparison, automatic discovery of an induction predicate, or native Wang acceptance for E is claimed.</p><div class="flow"><div><strong>Complete declared inputs</strong>Theory-only has \(4\) entries; full-library has \(70\). All \(66\) contextual interfaces pass separate checks before E is invoked.</div><div><strong>Automatically found proof</strong>E derives the target directly from the theory. No target proof is supplied and no lemma is selected.</div><div><strong>Actual certificate boundaries</strong>Amber rows introduce globally fresh witnesses. Expand them to inspect the explicit reconstructed derivation and its independent check.</div></div></section>
<section class="panel" id="statement"><h2>The exact first-order statement.</h2>__STATEMENTS__<p>The original symbols <code>zero</code>, <code>succ</code> and <code>add</code> are displayed as \(0\), \(S\), and \(+\). They are uninterpreted first-order symbols constrained by the listed axioms; no hidden natural-number domain assumption or additional Peano axioms enters the external control.</p><p>The sole declared induction predicate is \(P(n)\equiv(0+n=n)\). It is generated mechanically for every target-bound variable in the complete frozen catalog; here there is exactly one such variable and one instance. The inventory is derived from the whole catalog, not from the winning proof path. This target-driven predicate/template was supplied by the experimental design to both searches; it was not learned by RL.</p><p><a href="induction_receptors.html?v=20261011-ir1#reader">Read the separately audited native GCTS proof</a>.</p></section>
<section class="panel" id="comparison"><h2>The external control succeeds without its library.</h2><div class="scroll-table"><table><thead><tr><th>Input lane</th><th>Run</th><th>E binary ms</th><th>Check worker ms</th><th>Full replay worker ms</th><th>Lines</th><th>Lemma inputs used</th></tr></thead><tbody>__ROWS__</tbody></table></div><p>E solves this same small quantified assertion far more cheaply than the native bounded GCTS path. That practical observation gives no competitive advantage to GCTS+RL on this case. The learned policy and receptor inventory must earn their value on additional assertions that are not chosen to fit a known proof.</p><p>The two lanes expose the same exact finite theory; the second adds all admitted interfaces, with their complete upfront validation charged. E’s calculus permits broader term and quantifier instantiation than the native seven-row, four-node-term catalog. In particular, \(57\) interfaces with free eigenvariables were explicitly universally closed for E. Same axiom and interface formulas do not imply an identical search grammar, certificate language or native schema. There is no formal speed ratio.</p><p>The native run explored \(950\) recorded nodes in about \(1.57\) seconds, including graph construction and proposals. Its original whole query was unknown under a native space bound; a mechanical compaction later produced the accepted \(30\)-command whole certificate. That separately audited native acceptance and E’s fully checked independent refutation are distinct evidence. Compiler, admission, checking and prior audit costs remain visible below.</p></section>
<section class="panel" id="reader"><h2>Read each actual returned formula.</h2><p>English describes each formula and how the displayed parent lines justify it. Variables are local to each formula. Fresh constants \(w_{1}\) and \(w_{2}\) are display aliases declared separately for each run; E’s counterexample spelling differs between the lanes. The exact original symbols, source annotations and full certificates remain available in the evidence controls. These are first-order proof rows, not native Wang tiles or GCTS marking visualizations.</p><div class="controls"><label for="external-proof-control">Actual fresh run</label><select id="external-proof-control">__OPTIONS__</select></div>__PANELS__</section>
<section class="panel" id="checking"><h2>Conservative extensions share one context.</h2><p>The checker initially reserves every original input symbol, including unused library entries. It checks the exact file-backed formula against its original AST, registers a correct negation of the sole conjecture, and forbids using the positive conjecture as an ordinary premise. Every ordinary child has an independently replayed consequence certificate from its actual earlier parents.</p><p>A fresh-witness step has different semantics from an ordinary consequence. Every model of the existing shared context must admit an expansion satisfying the reconstructed witness formula. Lexical quantifier paths, full surrounding-universal dependencies, arities and global freshness are checked by the unchanged strict prototype. The reconstructed witness formula becomes part of the same context; later introductions reserve all earlier witnesses.</p><p>E compresses NNF, variable renaming, Skolemization, quantifier shifting and distribution into nested source annotations without printing their intermediate formulas. The adapter accepts a restricted unary chain containing exactly one Skolem node and supplies a separate explicit derivation: equivalent parent NNF, strict witness extension, then an independently certified consequence to the displayed child. It certifies the printed compound relation; it does not assert that E’s unprinted implementation intermediates have been reproduced verbatim. Unsupported chains, fresh predicates/definitions, omitted witnesses and dependency mismatches remain unknown.</p><p>Local consequence checks use uniform propositional abstraction, exact alpha-NNF equality, or a finite Herbrand/EUF refutation. A finite collection of universal ground instances is accepted only with an actual refutation whose binary branches and equality-conflict leaves replay independently. Satisfiable ground instances remain unknown. Negative universals receive polarity-correct existential witnesses; finite-domain satisfiability is never used to justify unrestricted quantified entailment.</p><p>All \(92\) prior native computations are exactly bound to their authoritative passed audits, including all \(66\) admissions, preserved original unknowns and the accepted compacted target. This is reused native evidence, not a rerun or a native Wang validation of the E outputs. The parser, formula transformations and certificate replay code remain trusted implementation code; this checker is not formally verified.</p><p>The source annotation semantics follow the <a href="https://tptp.org/UserDocs/TPTPLanguage/TPTPLanguage.shtml">official TPTP language</a>. E’s <a href="https://github.com/eprover/eprover/blob/3b7afc70fe77d3118bb95144c4735ca45f5f31cf/README.md">official README</a> warns that bundled <code>checkproof</code> skips non-clausal transformations; that tool was not used to establish these results. The pinned <a href="https://github.com/eprover/eprover/blob/3b7afc70fe77d3118bb95144c4735ca45f5f31cf/CLAUSES/ccl_tcnf.c">official clausifier implementation</a> creates fresh Skolem functions from scoped universals; our reconstruction checks those requirements independently.</p></section>
<section class="panel" id="inventory"><h2>Every admitted interface, with its exact dependencies.</h2><p>All \(66\) explicitly closed interfaces receive a fresh logical certificate from their exported axiom and finite-schema dependencies. Every certificate is replayed before E starts and again in the independent audit. The same full inventory is supplied to both library runs; the target proof references none of it. Original native definition/admission digests and exact formula ASTs are preserved in each record.</p>__INVENTORY__</section>
<section class="panel" id="history"><h2>The earlier unknown checks remain part of the result.</h2><p>The first preparation attempt encountered a sandbox-denied process-RSS query after its first interface worker launch. No E target run occurred; the unrecorded parent elapsed time remains unknown. A self-accounting worker replaced that unsupported process query.</p><p>The next frozen attempt completed all interface gates and four balanced E runs. E reported <code>Theorem</code> each time, but all four independent checks were <em>unknown</em> because the adapter supported only isolated Skolem nodes. Those exact \(568\) files, including source snapshots, traces, checks and costs, remain byte-preserved. The rejection was evidence of a real certificate-serialization gap, not a negative mathematical result.</p><p>The compact adapter was developed after seeing those traces. A separately saved development calibration checked one old theory trace; it is not counted among the four fresh controlled results. The new revision, exact inputs, budgets and reversed second-run lane order were then frozen before all fresh setup and target measurements. This is a corrected experimental retry, not a blind holdout or an independent discovery of a new proof family.</p><p>Preserved failed-validation attempt: E binary total __OLD_E__ seconds; rejected-check worker total __OLD_CHECK__ seconds; setup __OLD_SETUP__ seconds. Development calibration worker: __CALIBRATION__ seconds. Prototype and adapter development time was not instrumented and remains unknown. The full evidence includes both attempts.</p></section>
<section class="panel" id="costs"><h2>Setup, search and validation have separate costs.</h2><div class="scroll-table">__COSTS__</div><p class="small">Worker operation clocks include module imports and logical work; worker process clocks additionally include startup, monitoring and output serialization and are saved per operation. Parent progress-summary timers are sampled before their final summary write, so those last writes are excluded from the saved elapsed value. The all-interface completion clock in the tool output was \(18.043442042\) seconds; the saved progress timer is shown in the table. Timings are not additive when an orchestration row contains its child operations.</p><p>Fresh E processes request a \(60\)-second CPU limit and \(1024\)-MiB memory limit, with a \(65\)-second external wall cutoff. Certificate workers have a \(300\)-second whole-proof bound and \(30\)-second local consequence bounds. Their own high-water resident size is sampled every \(25\) milliseconds; an observed \(1\)-GiB breach terminates the worker. This is sampled supervision, not an instantaneous allocation cap. Interface workers have a \(30\)-second bound. Warm filesystem caches and concurrent research activity limit latency attribution.</p><p>The pinned E source/build is reused from the earlier control. Its recorded rebuild took about \(30.21\) seconds with about \(146.45\) MiB peak resident memory; original source acquisition/configuration time was unmeasured. The binary reports a <code>DEBUG</code> build and an embedded revision different from the pinned checkout; both identities are retained verbatim. No fresh rebuild or native computation was charged as new work here.</p><p class="small">Source commit <code>3b7afc70fe77d3118bb95144c4735ca45f5f31cf</code>; binary SHA-256 <code>__BINARY_SHA__</code>; version <code>__VERSION__</code>.</p></section>
<section class="panel" id="evidence"><h2>The independent audit and reproducible evidence.</h2><p>The audit replays \(4\) successful derivations, \(76\) actual returned lines, \(8\) conservative-extension boundaries and all \(66\) interface certificates. It binds all \(92\) audited native computations, both complete \(4/70\)-entry inputs, frozen source bytes and the preserved four unknown checks. It rejects \(92\) corruptions, including \(56\) logical refutation trees, altered original inputs, empty contradiction parents, incorrect transformation relations, captured dependencies, stale witness names and corrupted shared-context registries. The \(51\) development fixtures include finite-domain and quantifier-order counterexamples that an unsound approximation would admit.</p><p><a href="external_induction_tstp_control_data.json.gz">Byte-preserved complete evidence</a> · <a href="external_induction_tstp_control_plan.json">Frozen new plan</a> · <a href="external_induction_tstp_control_summary.json">Measurements</a> · <a href="external_induction_tstp_control_audit.json">Audit and corruptions</a></p><p><a href="../../../research/gcts-rl-renewal/external_induction_tstp_check.py">Shared-context adapter</a> · <a href="../../../research/gcts-rl-renewal/external_induction_skolem.py">Unchanged strict witness prototype</a> · <a href="../../../research/gcts-rl-renewal/external_prover_check.py">Unchanged Herbrand/EUF checker</a> · <a href="../../../research/gcts-rl-renewal/external_induction_tstp_tests.py">Adversarial fixtures</a> · <a href="../../../research/gcts-rl-renewal/external_induction_tstp_audit.py">Complete saved-evidence audit</a> · <a href="../../../research/gcts-rl-renewal/external_induction_tstp_run.py">Original frozen runner</a> · <a href="../../../research/gcts-rl-renewal/external_induction_tstp_reproduce.py">Fresh-output reproduction driver</a></p><details><summary>Reproduce the first-order control from the repository root</summary><pre># Build the official E source at the pinned revision documented above.
PYTHONPYCACHEPREFIX=/private/tmp/gcts-native-wang-pycache python3 research/gcts-rl-renewal/external_induction_tstp_reproduce.py --output .gcts-active/external-induction-tstp-reproduce --e /private/tmp/gcts-external-eprover-20261011/PROVER/eprover
# The output directory must be new. Existing frozen evidence is preserved.
# A different binary is recorded as a new experiment, not the original timing.</pre></details><p class="small">The evidence download preserves exact UTF-8 artifact and source bytes with SHA-256 digests, original formula inventories, native audit bindings, every local certificate and both completed experiment histories. Reproduction rechecks the interfaces and runs the unchanged universal target afresh. Full native proof-tape replay belongs to the separately published native notebook.</p></section></main><footer>Finite induction-instance comparison · automatic E search · separate complete first-order certificate check</footer><script>document.getElementById('external-proof-control').addEventListener('change',async function(){for(const p of document.querySelectorAll('.proof-panel'))p.hidden=p.id!=='proof-'+this.value;if(window.MathJax?.typesetPromise)await MathJax.typesetPromise([document.getElementById('proof-'+this.value)]);});</script></body></html>'''
    values={'STATEMENTS':''.join(statements),'ROWS':''.join(rows),'OPTIONS':''.join(options),'PANELS':''.join(panels),'INVENTORY':''.join(inventory),'COSTS':cost_html,'OLD_E':seconds(old_e),'OLD_CHECK':seconds(old_check),'OLD_SETUP':seconds(failed['setup_seconds']),'CALIBRATION':seconds(load(OUT/'calibration-theory-r1.json')['operation_seconds']),'BINARY_SHA':plan['prover_binary_sha256'],'VERSION':esc(plan['prover_version'])}
